    // cg_fp_rm
    $fwrite(fd, "cg_fp_rm.rne                %0d\n", cov_rm_rne);
    $fwrite(fd, "cg_fp_rm.rtz                %0d\n", cov_rm_rtz);
    $fwrite(fd, "cg_fp_rm.rdn                %0d\n", cov_rm_rdn);
    $fwrite(fd, "cg_fp_rm.rup                %0d\n", cov_rm_rup);
    $fwrite(fd, "cg_fp_rm.rmm                %0d\n", cov_rm_rmm);
